346	// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
347	// by searching /full/current first, then archived generations in reverse order.
348	// If not found locally, attempts to discover and fetch remote /full/* refs.
349	func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
350		if err := ctx.Err(); err != nil {
351			return nil, err //nolint:wrapcheck // Propagating context cancellation
352		}
353	
354		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
355	
356		// Search locally first
357		transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
358		if err == nil && len(transcript) > 0 {
359			return transcript, nil
360		}
361	
362		archived, err := s.ListArchivedGenerations()
363		if err != nil {
364			return nil, err
365		}
366		for i := len(archived) - 1; i >= 0; i-- {
367			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + archived[i])
368			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
369			if err == nil && len(transcript) > 0 {
370				return transcript, nil
371			}
372		}
373	
374		// Not found locally — try fetching remote /full/* refs
375		if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
376			logging.Debug(ctx, "failed to fetch remote /full/* refs",
377				slog.String("error", fetchErr.Error()),
378			)
379			return nil, nil
380		}
381	
382		// Search newly fetched refs only
383		newArchived, err := s.ListArchivedGenerations()
384		if err != nil {
385			return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume
386		}
387		existingSet := make(map[string]bool, len(archived))
388		for _, a := range archived {
389			existingSet[a] = true
390		}
391		for i := len(newArchived) - 1; i >= 0; i-- {
392			if existingSet[newArchived[i]] {
393				continue
394			}
395			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + newArchived[i])
396			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
397			if err == nil && len(transcript) > 0 {
398				return transcript, nil
399			}

