831	func listCommittedForExplain(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, preferCheckpointsV2 bool) ([]checkpoint.CommittedInfo, error) {
832		v1Committed, v1Err := v1Store.ListCommitted(ctx)
833	
834		if !preferCheckpointsV2 {
835			if v1Err != nil {
836				return nil, fmt.Errorf("listing v1 checkpoints: %w", v1Err)
837			}
838			return v1Committed, nil
839		}
840	
841		v2Committed, v2Err := v2Store.ListCommitted(ctx)
842		if v2Err != nil {
843			logging.Debug(ctx, "v2 ListCommitted failed, using v1 only",
844				slog.String("error", v2Err.Error()),
845			)
846			if v1Err != nil {
847				return nil, fmt.Errorf("listing checkpoints: %w", v1Err)
848			}
849			return v1Committed, nil
850		}
851	
852		if v1Err != nil {
853			logging.Debug(ctx, "v1 ListCommitted failed, returning v2 only",
854				slog.String("error", v1Err.Error()),
855			)
856			return v2Committed, nil
857		}
858	
859		// Merge v2 and v1 results so pre-v2 checkpoints remain visible during transition.
860		seen := make(map[id.CheckpointID]struct{}, len(v2Committed))
861		for _, c := range v2Committed {
862			seen[c.CheckpointID] = struct{}{}
863		}
864		committedCheckpoints := make([]checkpoint.CommittedInfo, 0, len(v2Committed)+len(v1Committed))
865		committedCheckpoints = append(committedCheckpoints, v2Committed...)
866		for _, c := range v1Committed {
867			if _, ok := seen[c.CheckpointID]; !ok {
868				committedCheckpoints = append(committedCheckpoints, c)
869			}
870		}
871		return committedCheckpoints, nil
872	}
