package main

import (
	"context"
	"crypto/md5"
	"fmt"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/go-git/go-git/v6"
)

func main() {
	repo, err := git.PlainOpen("/Users/alisha/Projects/devenv/cli")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open: %v\n", err)
		os.Exit(1)
	}

	v1 := checkpoint.NewGitStore(repo)
	cpID, _ := id.NewCheckpointID("2da5d3818b9b")

	ctx := context.Background()

	summary, err := v1.ReadCommitted(ctx, cpID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "ReadCommitted: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("v1 summary sessions=%d\n", len(summary.Sessions))

	for idx := 0; idx < len(summary.Sessions); idx++ {
		c, err := v1.ReadSessionContent(ctx, cpID, idx)
		if err != nil {
			fmt.Printf("idx=%d err=%v\n", idx, err)
			continue
		}
		fmt.Printf("idx=%d session=%s transcript_len=%d transcript_md5=%x\n",
			idx, c.Metadata.SessionID, len(c.Transcript), md5.Sum(c.Transcript))
	}
}

