// streamTranscriptToStdout copies the contents of f to w. Cancellation is
// wired through a goroutine that closes f on <-ctx.Done(), so io.Copy returns
// promptly when the user hits Ctrl-C on a multi-MB transcript instead of
// blocking until EOF. The trailing partial line (if the agent is mid-write
// when we hit EOF) is trimmed so consumers never see a truncated JSONL
// record. Returns ctx.Err() when cancellation triggered the abort.
func streamTranscriptToStdout(ctx context.Context, w io.Writer, f *os.File) error {
	closeOnDone := make(chan struct{})
	defer close(closeOnDone)
	go func() {
		select {
		case <-ctx.Done():
			_ = f.Close() //nolint:errcheck // Best-effort: close to unblock the io.Copy
		case <-closeOnDone:
		}
	}()

	// Read into a buffer so we can trim a trailing partial line; transcripts
	// are bounded (a single session, multi-MB at most) which is acceptable
	// for buffered handling. If this ever becomes a memory pressure point
	// we can switch to a line-aware Writer wrapper.
	buf, err := io.ReadAll(f)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return ctxErr //nolint:wrapcheck // Propagating context cancellation
		}
		return fmt.Errorf("read transcript: %w", err)
	}

	if i := bytes.LastIndexByte(buf, '\n'); i >= 0 {
		buf = buf[:i+1]
	}
	// All content before the last newline is shape-clean; if the file held a
	// single non-terminated record (vanishingly rare for live transcripts),
	// `buf` is now empty — that's the right behavior since we can't produce a
	// shape-clean snapshot.

	if _, err := w.Write(buf); err != nil {
		return fmt.Errorf("write transcript: %w", err)
	}
	return nil
}

