// resolveSessionBranch opens the worktree at path and returns the current
// branch name, or "" on any error or detached-HEAD state. Best-effort —
// callers omit empty values from JSON output.
func resolveSessionBranch(worktreePath string) string {
	if worktreePath == "" {
		return ""
	}
	repo, err := git.PlainOpen(worktreePath)
	if err != nil {
		return ""
	}
	return strategy.GetCurrentBranchName(repo)
}

