// requirement (#1125): consumers need both the user-facing branch name and
// the shadow-branch base commit so they can construct deep-links / resume
// commands without re-running git themselves.
func TestInfoCmd_JSONIncludesBranchAndBaseCommit(t *testing.T) {
	setupStopTestRepo(t)
	ctx := context.Background()

	cwd, err := os.Getwd()
	if err != nil {
		t.Fatalf("Getwd: %v", err)
	}

	state := makeSessionState("test-info-branch", session.PhaseActive)
	state.AgentType = testAgentClaude
	state.WorktreePath = cwd
	state.BaseCommit = "deadbeef0123456789abcdef0123456789abcdef"
	if err := strategy.SaveSessionState(ctx, state); err != nil {
		t.Fatalf("SaveSessionState: %v", err)
	}

	cmd := newInfoCmd()
	var stdout bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetArgs([]string{"test-info-branch", "--json"})
	if err := cmd.ExecuteContext(ctx); err != nil {
		t.Fatalf("ExecuteContext: %v", err)
	}

	var got sessionInfoJSON
	if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
		t.Fatalf("expected valid JSON, got: %v\noutput: %s", err, stdout.String())
	}
	if got.BaseCommit != state.BaseCommit {
		t.Errorf("expected base_commit=%q, got %q", state.BaseCommit, got.BaseCommit)
