	// is whatever git's init.defaultBranch resolves to (usually "main" or
	// "master"). Either is fine — what matters is that we resolved *some*
	// branch instead of returning an empty string.
	if got.Branch == "" {
		t.Error("expected non-empty branch field after worktree resolution")
	}
}

